class vector3d {
public:
  float x, y, z;
  vector3d() {}
  vector3d(float X, float Y, float Z) : x(X), y(Y), z(Z) {}
  vector3d operator-(const vector3d &b) const { return vector3d(x-b.x, y-b.y, z-b.z); }
  vector3d operator+(const vector3d &b) const { return vector3d(x+b.x, y+b.y, z+b.z); }
  vector3d operator*(float s) const { return vector3d(x*s, y*s, z*s); }
};

struct surface_point_t { char pad[1128]; vector3d pos; };
struct trail_node_t { char pad[12]; surface_point_t pnt2; };
struct spray_control_t {
  vector3d current __attribute__((aligned(16)));
  vector3d start __attribute__((aligned(16)));
  vector3d *trailpt;
  trail_node_t *trail_node;
  vector3d vel;
  float seed;
  float age;
  float life;
  int valid;
};
struct board_spray_t {
  float angle_scale, vel_scale, bonus_y, tex_size, tex_speed, tex_scale, grav, curve;
};
struct fx_data_t { char pad[23156]; float Trail_Start_Width_Mod; };
extern board_spray_t board_spray;
extern fx_data_t FXD;

class trail {
public:
  void spraypt_pos(spray_control_t *SC);
};

void trail::spraypt_pos (spray_control_t *SC)
{
	vector3d Grav (0, board_spray.grav, 0);

	SC->start = (*(SC->trailpt) - SC->trail_node->pnt2.pos) * FXD.Trail_Start_Width_Mod + SC->trail_node->pnt2.pos;
	SC->current = SC->start + (SC->vel * SC->age) + (Grav * SC->age * SC->age * 0.5f);
}
